import { addMenusApi, addMenus, getRuleList } from "@/api/systemMenus";
import icon from "@/utils/icon";

export default {
    name: "menusFrom",
    props: {
        formValidate: {
            type: Object,
            default: null,
        },
        titleFrom: {
            type: String,
            default: "",
        },
    },
    data() {
        return {
            arrs: [],
            searchRule: "",
            iconVal: "",
            grid: {
                xl: 12,
                lg: 12,
                md: 12,
                sm: 24,
                xs: 24,
            },
            modals: false,
            modal12: false,
            ruleValidate: {
                // menu_name: [
                //   { required: true, message: "请输入按钮名称", trigger: "blur" },
                // ],
                // menu_path: [
                //   { required: true, message: "请输入路由名称", trigger: "blur" },
                // ],
                // methods: [
                //   { required: true, message: "请选择接口请求方式", trigger: "blur" },
                // ],
                // api_url: [
                //   { required: true, message: "请填写接口请求地址", trigger: "blur" },
                // ],
            },
            FromData: [],
            valids: false,
            list2: [],
            list: icon,
            authType: true,
            search: icon,
            ruleModal: false,
            ruleList: [],
        };
    },
    watch: {
        "formValidate.header": function(n) {
            this.formValidate.is_header = n ? 1 : 0;
        },
        "formValidate.auth_type": function(n) {
            if (n === undefined) {
                n = 1;
            }
            this.authType = n === 1;
        },
        "formValidate.data": function(n) {},
    },
    computed: {
        /* eslint-disable */
        optionsList() {
            let a = [];
            this.FromData.map((item) => {
                if ("pid" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        headerOptionsList() {
            let a = [];
            this.FromData.map((item) => {
                if ("header" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        optionsListmodule() {
            let a = [];
            this.FromData.map((item) => {
                if ("module" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        optionsRadio() {
            let a = [];
            this.FromData.map((item) => {
                if ("auth_type" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        isheaderRadio() {
            let a = [];
            this.FromData.map((item) => {
                if ("is_header" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        isShowRadio() {
            let a = [];
            this.FromData.map((item) => {
                if ("is_show" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        isShowPathRadio() {
            let a = [];
            this.FromData.map((item) => {
                if ("is_show_path" === item.field) {
                    a = item.options;
                }
            });
            return a;
        },
        menuList() {
            let a = [];
            this.FromData.map((item) => {
                if ("menu_list" === item.field) {
                    a = item.props.data;
                }
            });
            return a;
        },
    },
    methods: {
        // 获取权限列表
        getRuleList() {
            getRuleList(4).then((res) => {
                this.ruleList = res.data;
                this.ruleModal = true;
            });
        },
        modalchange(type) {
            if (!type) {
                this.arrs = [];
                this.ruleModal = "";
                this.ruleModal = false;
            }
        },
        visible(type) {
            if (!type) {
                this.authType = true;
            }
        },
        selectRule(data) {
            this.$emit("selectRule", data);
            this.$nextTick((e) => {
                this.ruleModal = false;
            });
            // this.$set(this, "ruleModal", false);
        },
        changeRadio(n) {
            this.authType = n === 1 ? true : false;
        },
        // 搜索
        upIcon(n) {
            let arrs = [];
            for (var i = 0; i < this.search.length; i++) {
                if (this.search[i].type.indexOf(n) !== -1) {
                    arrs.push(this.search[i]);
                    this.list = arrs;
                }
            }
        },
        // 搜索规则
        searchRules() {
            if (this.searchRule.trim()) {
                this.arrs = [];
                for (var i = 0; i < this.ruleList.length; i++) {
                    if (this.ruleList[i].real_name.indexOf(this.searchRule) !== -1) {
                        this.arrs.push(i);
                    }
                }
            } else {
                this.arrs = [];
            }
        },
        init() {
            this.searchRule = "";
            this.arrs = [];
        },
        handleCreate1(val) {
            this.headerOptionsList.push({
                value: val,
                label: val,
            });
        },
        // 获取新增表单
        getAddFrom() {
            addMenus(4)
                .then(async (res) => {
                    this.FromData = res.data.rules;
                })
                .catch((res) => {
                    this.$Message.error(res.msg);
                });
        },
        iconClick() {
            this.modal12 = true;
        },
        iconChange(n) {
            this.formValidate.icon = n;
            this.modal12 = false;
        },
        // 提交
        handleSubmit(name) {
            //判断是否选择父级分类
            if (this.formValidate.path) {
                let length = this.formValidate.path.length;
                this.formValidate.pid = this.formValidate.path[length - 1] || 0;
            }
            let data = {
                url: this.formValidate.id
                    ? `/setting/menus/${this.formValidate.id}?type=4`
                    : "/setting/menus?type=4",
                method: this.formValidate.id ? "put" : "post",
                datas: this.formValidate,
            };
            if(this.authType){
                if(!this.formValidate.menu_name){
                    return this.$Message.error("请添加按钮名称！");
                }
                if(!this.formValidate.menu_path){
                    return this.$Message.error("请添加路由地址！");
                }
            }else{
                if (!this.formValidate.menu_name){
                    return this.$Message.error("请添加接口名称！");
                }
                if(!this.formValidate.api_url){
                    return this.$Message.error("请添加接口地址！");
                }
            }
            this.$refs[name].validate((valid) => {
                if (valid) {
                    this.valids = true;
                    addMenusApi(data)
                        .then(async (res) => {
                            this.$Message.success(res.msg);
                            this.modals = false;
                            this.$emit("getList");
                            this.getAddFrom();
                            this.$store.dispatch("admin/menus/getMenusNavList");
                        })
                        .catch((res) => {
                            this.valids = false;
                            this.$Message.error(res.msg);
                        });
                }
            });
        },
        handleReset() {
            this.modals = false;
            this.authType = true;
            this.$emit("clearFrom");
        },
    },
    created() {
        this.list = this.search;
        this.getAddFrom();
    },
};
